#include <vector>
#include <cstddef>
#include <cmath>
#include <algorithm>
#include <omp.h>

struct COOElement {
   size_t row, column;
   double value;
};

void solveLinearSystem(std::vector<COOElement> const& A,
                       std::vector<double> const& b,
                       std::vector<double> &x,
                       size_t N)
{
    x.assign(N, 0.0);
    if (N == 0) return;

    // Build CSR from COO (thread-safe counting + prefix sum + scatter with atomics)
    std::vector<size_t> rowPtr(N + 1, 0);

    // Count nnz per row
    #pragma omp parallel for
    for (std::ptrdiff_t k = 0; k < static_cast<std::ptrdiff_t>(A.size()); ++k) {
        const size_t r = A[static_cast<size_t>(k)].row;
        if (r < N) {
            #pragma omp atomic update
            rowPtr[r + 1] += 1;
        }
    }

    // Prefix sum (serial)
    for (size_t i = 0; i < N; ++i) rowPtr[i + 1] += rowPtr[i];

    const size_t nnz = rowPtr[N];
    std::vector<size_t> colInd(nnz, 0);
    std::vector<double> vals(nnz, 0.0);

    // Row offsets for scatter
    std::vector<size_t> rowNext = rowPtr;

    // Scatter COO into CSR
    #pragma omp parallel for
    for (std::ptrdiff_t k = 0; k < static_cast<std::ptrdiff_t>(A.size()); ++k) {
        const COOElement e = A[static_cast<size_t>(k)];
        if (e.row >= N || e.column >= N) continue;

        size_t pos;
        #pragma omp atomic capture
        { pos = rowNext[e.row]++; }

        colInd[pos] = e.column;
        vals[pos]   = e.value;
    }

    // Conjugate Gradient for SPD systems (best-effort; if not SPD, may not converge)
    auto dot = [&](std::vector<double> const& u, std::vector<double> const& v) -> double {
        double sum = 0.0;
        #pragma omp parallel for reduction(+:sum)
        for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(N); ++i)
            sum += u[static_cast<size_t>(i)] * v[static_cast<size_t>(i)];
        return sum;
    };

    auto matvec = [&](std::vector<double> const& in, std::vector<double> &out) {
        out.assign(N, 0.0);
        #pragma omp parallel for
        for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(N); ++i) {
            const size_t row = static_cast<size_t>(i);
            double acc = 0.0;
            for (size_t p = rowPtr[row]; p < rowPtr[row + 1]; ++p) {
                acc += vals[p] * in[colInd[p]];
            }
            out[row] = acc;
        }
    };

    std::vector<double> r(N, 0.0), p(N, 0.0), Ap(N, 0.0);

    // r = b - A*x (x=0 => r=b)
    r = b;
    p = r;

    double rr = dot(r, r);
    if (!std::isfinite(rr) || rr == 0.0) return;

    const double bnorm = std::sqrt(rr);
    const double tol = 1e-12;
    const size_t maxIters = std::max<size_t>(1, 10 * N);

    for (size_t iter = 0; iter < maxIters; ++iter) {
        matvec(p, Ap);

        const double pAp = dot(p, Ap);
        if (!std::isfinite(pAp) || std::abs(pAp) < 1e-300) break;

        const double alpha = rr / pAp;

        // x += alpha*p ; r -= alpha*Ap
        #pragma omp parallel for
        for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(N); ++i) {
            const size_t idx = static_cast<size_t>(i);
            x[idx] += alpha * p[idx];
            r[idx] -= alpha * Ap[idx];
        }

        const double rr_new = dot(r, r);
        if (!std::isfinite(rr_new)) break;

        if (std::sqrt(rr_new) <= tol * bnorm) break;

        const double beta = rr_new / rr;

        // p = r + beta*p
        #pragma omp parallel for
        for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(N); ++i) {
            const size_t idx = static_cast<size_t>(i);
            p[idx] = r[idx] + beta * p[idx];
        }

        rr = rr_new;
    }
}
